/// Start offset of each tree in `NODES`.
#[rustfmt::skip]
pub const TREE_STARTS: &[u32] = &[0, 15, 30, 45, 60, 75, 90, 105, 120, 135, 150, 165, 180, 195, 210, 225, 240, 255, 270, 285, 300, 315, 330, 345, 360, 375, 390, 405, 420, 433, 448, 463, 478, 493, 508, 523, 538, 553, 568, 581, 596, 611, 626, 641, 656, 671, 686, 701, 716, 729, 742, 757, 772, 787, 800, 815, 830, 843, 858, 873, 886, 897, 906, 921, 930, 945, 960, 975, 988, 1003, 1016, 1025, 1038, 1051, 1064, 1079, 1092, 1107, 1122, 1135, 1150, 1165, 1180, 1195, 1208, 1221, 1234, 1247, 1262, 1275, 1290, 1303, 1318, 1331, 1346, 1361, 1374, 1389, 1402, 1415];

/// Log-odds for a feature vector.
pub fn raw_score(x: &[f32; 20]) -> f32 {
    let mut raw = INIT_RAW;
    for &start in TREE_STARTS {
        let tree = &NODES[start as usize..];
        let mut i = 0usize;
        loop {
            let (feature, threshold, left, right, value) = tree[i];
            if feature < 0 {
                raw += LEARNING_RATE * value;
                break;
            }
            i = if x[feature as usize] <= threshold {
                left as usize
            } else {
                right as usize
            };
        }
    }
    raw
}
